import unittest

from app import full_name


class TestFullName(unittest.TestCase):
    def test_first_and_last(self):
        self.assertEqual(full_name('Ada', 'Lovelace'), 'Ada Lovelace')

    def test_a_single_name_stays_whole(self):
        self.assertEqual(full_name('Plato'), 'Plato')
